/**
 * Application types for the Business Management Portal
 * Matches backend ApplicationStatus enum from app/models/application.py
 */

export type ApplicationStatus =
  | 'ENQUIRY'
  | 'DRAFT'
  | 'SUBMITTED'
  | 'IN_REVIEW'
  | 'ACTION_REQUIRED'
  | 'APPROVED'
  | 'REJECTED'
  | 'COMPLETED'
  | 'CANCELLED';

export interface Application {
  id: number;
  application_number: string;
  customer_id: number;
  customer: {
    id: number;
    name: string;
    mobile: string;
    email?: string;
  };
  service_id: number;
  service: {
    id: number;
    name: string;
    description?: string;
  };
  status: ApplicationStatus;
  assigned_staff_id?: number | null;
  assigned_staff?: {
    id: number;
    full_name: string;
    email: string;
  } | null;
  application_data: Record<string, any>;
  notes?: string;
  created_at: string;
  updated_at: string;
}

export interface ApplicationListParams {
  shop_id: number;
  search?: string;
  status?: ApplicationStatus;
  service_id?: number;
  customer_id?: number;
  assigned_staff_id?: number;
  page?: number;
  page_size?: number;
}

export interface ApplicationListResponse {
  applications: Application[];
  total: number;
  page: number;
  page_size: number;
  total_pages: number;
}

export interface CreateApplicationRequest {
  customer_id: number;
  service_id: number;
  assigned_staff_id?: number;
  application_data?: Record<string, any>;
  notes?: string;
}

export interface UpdateApplicationRequest {
  application_data?: Record<string, any>;
  notes?: string;
  assigned_staff_id?: number | null;
  status?: ApplicationStatus;
}

export interface AssignStaffRequest {
  assigned_staff_id?: number | null;
}

export interface UpdateStatusRequest {
  status: ApplicationStatus;
}

export interface ServiceField {
  id: number;
  service_id: number;
  name: string;
  label: string;
  field_type: 'text' | 'number' | 'date' | 'select' | 'textarea' | 'boolean';
  is_required: boolean;
  options?: string[];
  help_text?: string;
  order: number;
}

export interface Service {
  id: number;
  shop_id: number;
  name: string;
  description?: string;
  status: 'active' | 'inactive' | 'archived';
  fields: ServiceField[];
  created_at: string;
  updated_at: string;
}

export interface Customer {
  id: number;
  shop_id: number;
  name: string;
  mobile: string;
  email?: string;
  address?: string;
  notes?: string;
  status: 'active' | 'inactive' | 'archived';
  primary_staff_id?: number;
  created_at: string;
  updated_at: string;
}

export interface User {
  id: number;
  email: string;
  full_name: string;
  is_active: boolean;
  platform_role?: string;
}

export interface ShopMembership {
  user_id: number;
  shop_id: number;
  role: 'owner' | 'manager' | 'staff';
  is_active: boolean;
}

export interface AuditLog {
  id: number;
  action: string;
  module: string;
  actor_user_id?: number;
  actor_role?: string;
  shop_id?: number;
  entity_type: string;
  entity_id: string;
  old_values?: Record<string, any>;
  new_values?: Record<string, any>;
  ip_address?: string;
  user_agent?: string;
  created_at: string;
}

'use client';

import { useAuth } from '@/lib/auth-context';
import { ProtectedRoute } from '@/components/protected-route';
import { useState, useEffect } from 'react';
import Link from 'next/link';
import {
  X,
  Check,
  Loader2,
  MessageCircleWarning,
  Calendar,
  Phone,
  Mail,
  MapPin,
  UserPlus
} from 'lucide-react';
import {
  Button,
  Input,
  Select,
  Textarea,
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
  Toast,
  ToastDescription,
  ToastTitle,
  Toaster,
  Tabs,
  TabsList,
  TabsTrigger,
  TabsContent
} from '@/components/ui';
import { z } from 'zod';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import {
  ApplicationStatus,
  ServiceField,
  Service,
  Customer,
  User
} from '@/src/types/application';

// Mock data - will be replaced with API calls
const MOCK_SHOP_DATA = {
  id: 1,
  code: 'TEST',
  name: 'Test Shop'
};

const MOCK_CUSTOMERS: Customer[] = [
  {
    id: 1,
    shop_id: 1,
    name: 'John Doe',
    mobile: '+919876543210',
    email: 'john@example.com',
    address: '123 Test St',
    notes: 'Regular customer',
    status: 'active',
    primary_staff_id: 1,
    created_at: '2026-09-01T10:00:00Z',
    updated_at: '2026-09-01T10:00:00Z'
  },
  {
    id: 2,
    shop_id: 1,
    name: 'Jane Smith',
    mobile: '+919876543211',
    email: 'jane@example.com',
    address: '456 Oak Ave',
    status: 'active',
    created_at: '2026-09-05T14:30:00Z',
    updated_at: '2026-09-05T14:30:00Z'
  }
];

const MOCK_SERVICES: Service[] = [
  {
    id: 1,
    shop_id: 1,
    name: 'Business Registration',
    description: 'Help with registering a new business',
    status: 'active',
    fields: [
      {
        id: 1,
        service_id: 1,
        name: 'business_name',
        label: 'Business Name',
        field_type: 'text',
        is_required: true,
        order: 1
      },
      {
        id: 2,
        service_id: 1,
        name: 'business_type',
        label: 'Business Type',
        field_type: 'select',
        is_required: true,
        options: ['Sole Proprietorship', 'Partnership', 'Private Limited', 'LLP'],
        order: 2
      },
      {
        id: 3,
        service_id: 1,
        name: 'registration_date',
        label: 'Preferred Registration Date',
        field_type: 'date',
        is_required: false,
        order: 3
      }
    ],
    created_at: '2026-09-01T09:00:00Z',
    updated_at: '2026-09-01T09:00:00Z'
  },
  {
    id: 2,
    shop_id: 1,
    name: 'Tax Consulting',
    description: 'Tax filing and consulting services',
    status: 'active',
    fields: [
      {
        id: 4,
        service_id: 2,
        name: 'client_name',
        label: 'Client Name',
        field_type: 'text',
        is_required: true,
        order: 1
      },
      {
        id: 5,
        service_id: 2,
        name: 'tax_year',
        label: 'Tax Year',
        field_type: 'select',
        is_required: true,
        options: ['2023-24', '2024-25', '2025-26'],
        order: 2
      },
      {
        id: 6,
        service_id: 2,
        name: 'annual_income',
        label: 'Annual Income (₹)',
        field_type: 'number',
        is_required: false,
        order: 3
      }
    ],
    created_at: '2026-09-01T09:00:00Z',
    updated_at: '2026-09-01T09:00:00Z'
  }
];

const MOCK_STAFF: User[] = [
  {
    id: 1,
    email: 'staff@test.com',
    full_name: 'Test Staff',
    is_active: true,
    platform_role: null
  },
  {
    id: 2,
    email: 'manager@test.com',
    full_name: 'Shop Manager',
    is_active: true,
    platform_role: null
  }
];

// Validation schema
const createApplicationSchema = z.object({
  customer_id: z.number(),
  service_id: z.number(),
  assigned_staff_id: z.number().optional(),
  application_data: z.record(z.string(), z.any()).optional(),
  notes: z.string().optional()
});

type CreateApplicationFormValues = z.infer<typeof createApplicationSchema>;

export default function NewApplicationPage() {
  const { user } = useAuth();
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [formData, setFormData] = useState<CreateApplicationFormValues>({
    customer_id: undefined,
    service_id: undefined,
    assigned_staff_id: undefined,
    application_data: {},
    notes: undefined
  });

  const {
    register,
    handleSubmit,
    watch,
    formState: { errors, isSubmitting },
    reset
  } = useForm<CreateApplicationFormValues>({
    resolver: zodResolver(createApplicationSchema),
    defaultValues: formData
  });

  // Watch for service changes to validate dynamic form
  const watchedService = watch('service_id');

  // Reset form when service changes
  useEffect(() => {
    if (watchedService) {
      // Reset application_data when service changes
      setFormData(prev => ({
        ...prev,
        application_data: {}
      }));
    }
  }, [watchedService]);

  // Handle customer selection
  const handleCustomerSelect = (customer: Customer) => {
    setSelectedCustomer(customer);
    setFormData(prev => ({
      ...prev,
      customer_id: customer.id
    }));
    setStep(2);
  };

  // Handle service selection
  const handleServiceSelect = (service: Service) => {
    setSelectedService(service);
    setFormData(prev => ({
      ...prev,
      service_id: service.id
    }));
    setStep(3);
  };

  // Handle staff assignment
  const handleStaffSelect = (staffId: number | undefined) => {
    setFormData(prev => ({
      ...prev,
      assigned_staff_id: staffId
    }));
  };

  // Handle dynamic field input
  const handleFieldChange = (fieldName: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      application_data: {
        ...prev.application_data,
        [fieldName]: value
      }
    }));
  };

  // Handle form submission
  const onSubmit = handleSubmit(async (data) => {
    setLoading(true);
    // TODO: Replace with actual API call
    try {
      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Success - redirect to applications list
      // In a real app, we'd get the created application ID from the response
      // and navigate to /dashboard/applications/[id]
      alert('Application created successfully!');
      // TODO: Replace with actual redirect
      // router.push('/dashboard/applications');
    } catch (error) {
      alert('Failed to create application. Please try again.');
    } finally {
      setLoading(false);
    }
  });

  // Go back to previous step
  const goBack = () => {
    if (step > 1) {
      setStep(step - 1);
    }
  };

  // Advance to next step
  const goNext = () => {
    if (step < 4) {
      setStep(step + 1);
    }
  };

  if (step === 1) {
    return (
      <ProtectedRoute>
        <div className="space-y-6">
          <div className="flex justify-between items-start mb-4">
            <h1 className="text-2xl font-bold">New Application</h1>
            <Link href="/dashboard/applications" className="text-sm text-muted-foreground hover:underline">
              ← Back to Applications
            </Link>
          </div>

          <div className="w-full max-w-2xl mx-auto">
            <div className="rounded-lg border bg-card p-6 shadow-sm">
              <h2 className="mb-4 text-lg font-semibold flex items-center gap-2">
                <Calendar className="h-5 w-5" />
                Step 1: Select Customer
              </h2>
              <p className="mb-4 text-muted-foreground">
                Choose the customer for this application
              </p>

              <div className="space-y-4">
                {MOCK_CUSTOMERS.map((customer) => (
                  <div
                    key={customer.id}
                    onClick={() => handleCustomerSelect(customer)}
                    className={`
                      cursor-pointer
                      rounded-lg border p-4 hover:bg-accent hover:text-accent-foreground
                      transition-all duration-200
                      ${selectedCustomer?.id === customer.id ? 'bg-primary/10 border-primary' : ''}
                    `}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-medium">{customer.name}</h3>
                        <p className="text-sm text-muted-foreground mb-1">
                          {customer.mobile}
                        </p>
                        {customer.email && (
                          <p className="text-xs text-muted-foreground">
                            {customer.email}
                          </p>
                        )}
                      </div>
                      <div className="flex-shrink-0">
                        {selectedCustomer?.id === customer.id ? (
                          <Check className="h-4 w-4 text-primary" />
                        ) : (
                          <div className="h-4 w-4 rounded border/30 flex items-center justify-center">
                            <ChevronRight className="h-3 w-3 text-muted-foreground" />
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <Button
                onClick={goNext}
                disabled={!selectedCustomer}
                className="w-full"
              >
                {loading ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4" />
                    Loading...
                  </>
                ) : (
                  <>
                    <Check className="mr-2 h-4 w-4" />
                    Continue to Service Selection
                  </>
                )}
              </Button>
            </div>
          </div>
        </div>

        <Toaster />
      </ProtectedRoute>
    );
  }

  if (step === 2) {
    return (
      <ProtectedRoute>
        <div className="space-y-6">
          <div className="flex justify-between items-start mb-4">
            <h1 className="text-2xl font-bold">New Application</h1>
            <Link href="/dashboard/applications" className="text-sm text-muted-foreground hover:underline">
              ← Back to Applications
            </Link>
          </div>

          <div className="w-full max-w-2xl mx-auto">
            <div className="rounded-lg border bg-card p-6 shadow-sm">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h2 className="mb-2 text-lg font-semibold flex items-center gap-2">
                    <UserPlus className="h-5 w-5" />
                    Step 2: Select Service
                  </h2>
                  <p className="text-sm text-muted-foreground">
                    Selected customer: {selectedCustomer?.name}
                  </p>
                </div>
                <Button
                  variant="outline"
                  onClick={goBack}
                >
                  Back
                </Button>
              </div>

              <p className="mb-4 text-muted-foreground">
                Choose the service for this application
              </p>

              <div className="space-y-4">
                {MOCK_SERVICES.map((service) => (
                  <div
                    key={service.id}
                    onClick={() => handleServiceSelect(service)}
                    className={`
                      cursor-pointer
                      rounded-lg border p-4 hover:bg-accent hover:text-accent-foreground
                      transition-all duration-200
                      ${selectedService?.id === service.id ? 'bg-primary/10 border-primary' : ''}
                    `}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-medium">{service.name}</h3>
                        <p className="text-sm text-muted-foreground mb-1">
                          {service.description}
                        </p>
                        <div className="mt-2 flex flex-wrap gap-2">
                          {service.fields.map((field) => (
                            <span
                              key={field.id}
                              className={`
                                inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium
                                bg-muted/20 text-muted-foreground
                              `}
                            >
                              {field.label}{field.is_required && ' *'}
                            </span>
                          ))}
                        </div>
                      </div>
                      <div className="flex-shrink-0">
                        {selectedService?.id === service.id ? (
                          <Check className="h-4 w-4 text-primary" />
                        ) : (
                          <div className="h-4 w-4 rounded border/30 flex items-center justify-center">
                            <ChevronRight className="h-3 w-3 text-muted-foreground" />
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="flex justify-between pt-4 border-t">
                <Button
                  variant="outline"
                  onClick={goBack}
                >
                  Back
                </Button>
                <Button
                  onClick={goNext}
                  disabled={!selectedService}
                  className="w-fit"
                >
                  {loading ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4" />
                      Loading...
                    </>
                  ) : (
                    <>
                      <Check className="mr-2 h-4 w-4" />
                      Continue to Staff Assignment
                    </>
                  )}
                </Button>
              </div>
            </div>
          </div>

          <Toaster />
        </div>
      </ProtectedRoute>
    );
  }

  if (step === 3) {
    return (
      <ProtectedRoute>
        <div className="space-y-6">
          <div className="flex justify-between items-start mb-4">
            <h1 className="text-2xl font-bold">New Application</h1>
            <Link href="/dashboard/applications" className="text-sm text-muted-foreground hover:underline">
              ← Back to Applications
            </Link>
          </div>

          <div className="w-full max-w-2xl mx-auto">
            <div className="rounded-lg border bg-card p-6 shadow-sm">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h2 className="mb-2 text-lg font-semibold flex items-center gap-2">
                    <UserPlus className="h-5 w-5" />
                    Step 3: Assign Staff (Optional)
                  </h2>
                  <p className="text-sm text-muted-foreground">
                    Customer: {selectedCustomer?.name} &nbsp;|&nbsp;
                    Service: {selectedService?.name}
                  </p>
                </div>
                <Button
                  variant="outline"
                  onClick={goBack}
                >
                  Back
                </Button>
              </div>

              <p className="mb-4 text-muted-foreground">
                Assign a staff member to this application (optional)
              </p>

              <div className="space-y-4">
                <div className="flex items-center gap-3 p-4 rounded-lg border">
                  <div className="flex-shrink-0 h-8 w-8 rounded bg-muted/50 flex items-center justify-center">
                    <UserPlus className="h-4 w-4 text-muted-foreground" />
                  </div>
                  <div>
                    <p className="font-medium">Unassigned</p>
                    <p className="text-xs text-muted-foreground">
                      No staff member assigned
                    </p>
                  </div>
                </div>

                {MOCK_STAFF.map((staff) => (
                  <div
                    key={staff.id}
                    onClick={() => handleStaffSelect(staff.id)}
                    className={`
                      cursor-pointer
                      rounded-lg border p-4 hover:bg-accent hover:text-accent-foreground
                      transition-all duration-200
                      ${formData.assigned_staff_id === staff.id ? 'bg-primary/10 border-primary' : ''}
                    `}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-medium">{staff.full_name}</h3>
                        <p className="text-sm text-muted-foreground mb-1">
                          {staff.email}
                        </p>
                      </div>
                      <div className="flex-shrink-0">
                        {formData.assigned_staff_id === staff.id ? (
                          <Check className="h-4 w-4 text-primary" />
                        ) : (
                          <div className="h-4 w-4 rounded border/30 flex items-center justify-center">
                            <ChevronRight className="h-3 w-3 text-muted-foreground" />
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="flex justify-between pt-4 border-t">
                <Button
                  variant="outline"
                  onClick={goBack}
                >
                  Back
                </Button>
                <Button
                  onClick={goNext}
                  className="w-fit"
                >
                  {loading ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4" />
                      Loading...
                    </>
                  ) : (
                    <>
                      <Check className="mr-2 h-4 w-4" />
                      Continue to Application Details
                    </>
                  )}
                </Button>
              </div>
            </div>
          </div>

          <Toaster />
        </div>
      </ProtectedRoute>
    );
  }

  if (step === 4) {
    return (
      <ProtectedRoute>
        <div className="space-y-6">
          <div className="flex justify-between items-start mb-4">
            <h1 className="text-2xl font-bold">New Application</h1>
            <Link href="/dashboard/applications" className="text-sm text-muted-foreground hover:underline">
              ← Back to Applications
            </Link>
          </div>

          <div className="w-full max-w-2xl mx-auto">
            <Form onSubmit={onSubmit}>
              <div className="rounded-lg border bg-card p-6 shadow-sm">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h2 className="mb-2 text-lg font-semibold flex items-center gap-2">
                      <MessageCircleWarning className="h-5 w-5" />
                      Step 4: Application Details
                    </h2>
                    <p className="text-sm text-muted-foreground">
                      Customer: {selectedCustomer?.name} &nbsp;|&nbsp;
                      Service: {selectedService?.name} &nbsp;|&nbsp;
                      Staff: {formData.assigned_staff_id ?
                        MOCK_STAFF.find(s => s.id === formData.assigned_staff_id)?.full_name || 'Unknown' :
                        'Unassigned'}
                    </p>
                  </div>
                  <Button
                    variant="outline"
                    onClick={goBack}
                  >
                    Back
                  </Button>
                </div>

                <div className="space-y-6">
                  {/* Notes field */}
                  <FormField>
                    <FormLabel>
                      Notes (Optional)
                    </FormLabel>
                    <FormControl>
                      <Textarea
                        {...register('notes')}
                        placeholder="Add any additional notes about this application..."
                        className="h-20"
                      />
                    </FormControl>
                    <FormMessage>
                      {errors.notes?.message}
                    </FormMessage>
                    <FormDescription>
                      Optional notes for internal reference
                    </FormDescription>
                  </FormField>

                  {/* Dynamic form fields based on service */}
                  {selectedService?.fields && selectedService.fields.length > 0 && (
                    <fieldset>
                      <legend className="text-lg font-semibold mb-4">
                        Service Information
                      </legend>
                      <div className="space-y-4">
                        {selectedService.fields.map((field) => (
                          <FormField key={field.id}>
                            <FormLabel className="flex items-center justify-between">
                              <span>
                                {field.label}
                                {field.is_required && (
                                  <span className="text-destructive ml-1">*</span>
                                )}
                              </span>
                              <HelpTooltip helpText={field.help_text || ''}>
                                <InfoIcon className="h-3 w-3 ml-1 text-muted-foreground" />
                              </HelpTooltip>
                            </FormLabel>
                            <FormControl>
                              {renderFieldInput(field, register, handleFieldChange, formData.application_data[field.name] ?? '')}
                            </FormControl>
                            <FormMessage>
                              {errors.application_data?.message}
                            </FormMessage>
                            <FormDescription>
                              {field.help_text}
                            </FormDescription>
                          </FormField>
                        ))}
                      </div>
                    </fieldset>
                  )}

                  {selectedService?.fields && selectedService.fields.length === 0 && (
                    <p className="text-muted-foreground italic">
                      No additional information required for this service.
                    </p>
                  )}
                </div>

                <div className="pt-4 border-t">
                  <Button
                    type="submit"
                    disabled={isSubmitting}
                    className="w-full"
                  >
                    {isSubmitting ? (
                      <>
                        <Loader2 className="mr-2 h-4 w-4" />
                        Creating Application...
                      </>
                    ) : (
                      <>
                        <Check className="mr-2 h-4 w-4" />
                        Create Application
                      </>
                    )}
                  </Button>
                </div>
              </div>
            </Form>
          </div>

          <Toaster />
        </div>

        {/* Help tooltip component */}
        <HelpTooltip helpText="" />
      </ProtectedRoute>
    );
  }

  return null;
}

// Helper component for rendering different field types
function renderFieldInput(
  field: ServiceField,
  register: any,
  handleFieldChange: (fieldName: string, value: any) => void,
  currentValue: any
) {
  switch (field.field_type) {
    case 'text':
      return (
        <Input
          {...register(field.name)}
          value={currentValue}
          onChange={(e) => handleFieldChange(field.name, e.target.value)}
          placeholder={`Enter ${field.label.toLowerCase()}`}
          required={field.is_required}
        />
      );
    case 'textarea':
      return (
        <Textarea
          {...register(field.name)}
          value={currentValue}
          onChange={(e) => handleFieldChange(field.name, e.target.value)}
          placeholder={`Enter ${field.label.toLowerCase()}`}
          required={field.is_required}
          className="h-16"
        />
      );
    case 'number':
      return (
        <Input
          type="number"
          {...register(field.name)}
          value={currentValue}
          onChange={(e) => handleFieldChange(field.name, e.target.value === '' ? '' : Number(e.target.value))}
          placeholder={`Enter ${field.label.toLowerCase()}`}
          required={field.is_required}
        />
      );
    case 'date':
      return (
        <Input
          type="date"
          {...register(field.name)}
          value={currentValue}
          onChange={(e) => handleFieldChange(field.name, e.target.value)}
          required={field.is_required}
        />
      );
    case 'select':
      return (
        <Select>
          <SelectTrigger
            {...register(field.name)}
            value={currentValue}
            onValueChange={(value) => handleFieldChange(field.name, value)}
          >
            <SelectValue placeholder={`Select ${field.label.toLowerCase()}`} />
            <SelectContent>
              {field.options?.map((option) => (
                <SelectItem key={option} value={option}>
                  {option}
                </SelectItem>
              )) || []}
            </SelectContent>
          </SelectTrigger>
          <SelectLabel>{field.label}</SelectLabel>
          {field.is_required && <SelectItem disabled>This field is required</SelectItem>}
        </Select>
      );
    case 'boolean':
      return (
        <div className="flex items-center gap-2">
          <input
            type="checkbox"
            {...register(field.name)}
            checked={!!currentValue}
            onChange={(e) => handleFieldChange(field.name, e.target.checked)}
          />
          <span>{field.label}</span>
        </div>
      );
    default:
      return (
        <Input
          {...register(field.name)}
          value={currentValue}
          onChange={(e) => handleFieldChange(field.name, e.target.value)}
          placeholder={`Enter ${field.label.toLowerCase()}`}
          required={field.is_required}
        />
      );
  }
}

// Help tooltip component
function HelpTooltip({ helpText, className }: { helpText: string; className?: string }) {
  if (!helpText) return null;

  return (
    <div className="relative inline-block">
      <div className={className}>ⓘ</div>
      <div className="absolute left-0 top-8 w-48 rounded-md border bg-popover p-2 text-sm text-popover-foreground shadow-lg z-50">
        <p className="mb-0">{helpText}</p>
      </div>
    </div>
  );
}

// Info icon component
function InfoIcon({ className }: { className?: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 20 20"
      fill="currentColor"
      className={className}
      aria-hidden="true"
    >
      <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 100 2 1 1 0 000-2zm-1 5a1 1 0 00-.707 1.707l-.707.707a1 1 0 001.414 0l.707-.707a1 1 0 000-1.414z" clipRule="evenodd" />
    </svg>
  );
}

